from pathlib import Path
from datetime import datetime,timezone
import hashlib,json
from analyze import ROOT
def main():
    a=json.loads((ROOT/'data/processed/results.json').read_text());x=json.loads((ROOT/'data/processed/xinput-results.json').read_text());joyfile=ROOT/'data/processed/joystick-results.json';joy=json.loads(joyfile.read_text()) if joyfile.exists() else [];valid=[r for r in a+x+joy if r['status']=='measured']
    errors=[]
    for p in sorted((ROOT/'data/raw').rglob('*-error.json')):
        errors.append({'file':p.relative_to(ROOT).as_posix(),'error':json.loads(p.read_text()).get('error')})
    result={'updated_utc':datetime.now(timezone.utc).isoformat(),'mission_status':'partial_campaign_executed_open_driver_incident','measured_series':len(valid),'invalid_annotated_series':sum(r['status']!='measured' for r in a+x+joy),'native_error_records':errors,'dataset_sha256':{p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((ROOT/'data/processed').glob('*.json'))},'not_executed':{'physical_hardware':'No dedicated physical agent, USB assignment or external timing apparatus','oblitum_Interception':'User confirmed no commercial-use license; excluded from commercial performance measurements','libvirtualhid_Windows':'User confirmed no appropriate Windows license; no driver-backed performance score','Microsoft_VHF_UdeCx_samples':'Reference architecture/source reviewed; existing Vdevice and ViGEm generators covered selected paths, no new sample driver qualification claimed','long_duration_soak':'Multi-hour soak and fault injection not executed; any shorter monitored run is reported separately','full_protocol_matrix':'No exhaustive DualSense/Bluetooth/physical/XInputHID matrix; see actual DS4, XUSB and GIP per-run results','driver_stability':'Open WDF-001: Vdevice queue purge at STATUS_DELETE_PENDING caused a guest bugcheck during the controller campaign; initiating lifetime race not resolved','self_hosted_CI':'Workflow prepared; no dedicated runner registered or dispatched','search_console':'No verification token or account connection available'}}
    (ROOT/'reports/campaign-status.json').write_text(json.dumps(result,indent=2)+'\n')
    text=f"# Executed campaign report\n\nUpdated: {result['updated_utc']}\n\nThis is a partial, genuinely executed campaign, not completion of the full requested hardware/protocol/endurance matrix.\n\n- Valid measured series: **{len(valid)}**.\n- Invalid annotated series retained: **{result['invalid_annotated_series']}**.\n- Native error records retained: **{len(errors)}**.\n- Real driver installation and tests ran only inside the owned Hyper-V VM.\n- PnP snapshots and independent content checks gate filtered results.\n- No simulated ranking, purchased review, real user-input capture, private key or commercial package is published.\n\n## Remaining work and exact reasons\n\n| Item | Status / reason |\n|---|---|\n"
    text+='\n'.join(f'| {k} | {v} |' for k,v in result['not_executed'].items())
    text+='\n\n## Inspect evidence\n\nSee `data/raw/`, `data/processed/`, `reports/artifacts.json`, `reports/repository-audit.json`, `reports/clean-baseline-v2.txt`, per-run `pnp-stack.txt` and the documentation. The initial image included historical Filter packages; the corrected clean baseline removes them. Pilot results retain their original provenance and limitations.\n'
    (ROOT/'reports/EXECUTED.md').write_text(text,encoding='utf8');print('Campaign report generated:',len(valid),'measured series')
if __name__=='__main__':main()
